// npm i express express-session express-rate-limit bcrypt
const express = require('express');
const session = require('express-session');
const rateLimit = require('express-rate-limit');
const bcrypt = require('bcrypt');

const app = express();
app.use(express.json());
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    maxAge: 24 * 60 * 60 * 1000,
  },
}));

const users = new Map(); // username -> bcrypt hash

// Compared against when the username is unknown, so response time does not reveal which usernames exist.
const DUMMY_HASH = bcrypt.hashSync('dummy', 12);

// Only failed logins (responses with status >= 400) count toward the limit.
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many failed login attempts. Try again later.' },
});

app.post('/register', async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' || !username || password.length < 8) {
    return res.status(400).json({ error: 'A username and a password of at least 8 characters are required.' });
  }
  if (users.has(username)) return res.status(409).json({ error: 'That username is taken.' });
  users.set(username, await bcrypt.hash(password, 12));
  res.status(201).json({ ok: true });
});

app.post('/login', loginLimiter, async (req, res, next) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'A username and password are required.' });
  }
  const hash = users.get(username);
  const ok = await bcrypt.compare(password, hash ?? DUMMY_HASH);
  if (!hash || !ok) return res.status(401).json({ error: 'Invalid username or password.' });

  // A fresh session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.user = username;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('connect.sid');
    res.json({ ok: true });
  });
});

const requireAuth = (req, res, next) =>
  req.session.user ? next() : res.status(401).json({ error: 'You are not logged in.' });

app.get('/me', requireAuth, (req, res) => res.json({ user: req.session.user }));

app.listen(3000);
```

Set `SESSION_SECRET` to a long random value before starting it; nothing here was run.

- Users and sessions live in process memory, so move them to a database and a session store such as `connect-redis` before production or running more than one instance.
- The limiter counts per IP only, so add a per-username counter if you need to stop guessing spread across many IPs, and set `app.set('trust proxy', 1)` behind a reverse proxy, or every client shares one IP and the secure cookie is never set.
- There is no CSRF token; `sameSite: 'lax'` covers these JSON POST routes, but add one if you introduce form posts or state-changing GETs.
